	scores := make(map[string]float64, len(snapshots))

	// Compute comprehensive cluster load statistics
	maxLoad := 0
	minLoad := 999999
	totalLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		totalLoad += el
		if el > maxLoad {
			maxLoad = el
		}
		if el < minLoad {
			minLoad = el
		}
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots)+1)

	// Dual-signal load pressure: both imbalance and absolute load
	loadSpread := maxLoad - minLoad
	spreadPressure := 0.0
	if maxLoad > 1 {
		spreadPressure = float64(loadSpread) / float64(maxLoad+1)
