// Available scorers: prefix-affinity (proportional prefix match ratio),
// queue-depth (min-max normalization of EffectiveLoad),
// kv-utilization (1 - KVUtilization), load-balance (1/(1 + EffectiveLoad)).
// See sim/routing_scorers.go and sim/routing_prefix_scorer.go for implementations.
//
// Stateful scorers (prefix-affinity) register observers that update internal
// state after each routing decision. Observers are called after argmax selection.
//
// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	scores := make(map[string]float64, len(snapshots))

	// Compute load statistics across cluster
	maxLoad := 0
	minLoad := 999999
	totalLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		totalLoad += el
		if el > maxLoad {
			maxLoad = el
		}
		if el < minLoad {
			minLoad = el
		}
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots)+1)

	// Dual-signal pressure: spread imbalance + absolute congestion
	loadSpread := maxLoad - minLoad
	spreadPressure := 0.0
	if maxLoad > 1 {
		spreadPressure = float64(loadSpread) / float64(maxLoad+1)
	}
	absPressure := avgLoad / (avgLoad + 2.5)
	loadPressure := spreadPressure*0.55 + absPressure*0.45

	// Session affinity boost for multi-turn conversations
	sessionBoost := 0.0
	if req.SessionID != "" {
		sessionBoost = 0.3
	}

	// Dynamic weights: shift toward load-balance under pressure
	dynWeights := make([]float64, len(ws.weights))
	copy(dynWeights, ws.weights)
	if len(dynWeights) >= 2 {
		prefixW := ws.weights[0]*(1.0-0.85*loadPressure) + sessionBoost
		loadW := ws.weights[1] * (1.0 + 2.2*loadPressure)
		wSum := prefixW + loadW
		if wSum > 0.001 {
			dynWeights[0] = prefixW / wSum
			dynWeights[1] = loadW / wSum
		}
	}

	// Base scoring with dynamic weights
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * dynWeights[i]
		}
	}

	// Post-scoring adjustments using instance signals
	inputLen := len(req.InputTokens)
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		fEl := float64(el)

		// Quadratic load penalty - strong for tail latency
		if el > 0 {
			penalty := 1.0 / (1.0 + 0.22*fEl*fEl)
			scores[snap.ID] *= (0.2 + 0.8*penalty)
		}

		// Hard cutoff: heavily penalize instances far above average
		if fEl > avgLoad+2.5 && avgLoad > 0.3 {
			excess := (fEl - avgLoad) / (avgLoad + 1.0)
			scores[snap.ID] *= 0.08 / (0.08 + excess)
		}

		// Queue depth penalty (queued requests wait longest)
		if snap.QueueDepth > 1 {
			qPenalty := 1.0 / (1.0 + 0.25*float64(snap.QueueDepth))
			scores[snap.ID] *= (0.5 + 0.5*qPenalty)
